package handlers

import (
	"encoding/json"

	db "bizprofit/internal/database/db"

	"github.com/jackc/pgx/v5/pgtype"
)

// ErrorResponse — стандартный ответ с ошибкой.
type ErrorResponse struct {
	Error string `json:"error" validate:"required" example:"invalid credentials"`
}

// RenewalItem — одна строка в центре продлений (ФН/ОФД/софт).
type RenewalItem struct {
	Type           string  `json:"type" validate:"required" example:"fn" enums:"fn,ofd,software"`
	EntityID       int64   `json:"entity_id" validate:"required" example:"18714699"`
	ClientID       *int64  `json:"client_id,omitempty" example:"18714699"`
	ClientName     string  `json:"client_name" validate:"required" example:"ООО Лидер"`
	KassaID        *int64  `json:"kassa_id,omitempty" example:"18714699"`
	KassaModel     *string `json:"kassa_model,omitempty" example:"АТОЛ 25Ф"`
	SubscriptionID *int64  `json:"subscription_id,omitempty" example:"42"`
	Title          string  `json:"title" validate:"required" example:"ФН: АТОЛ 25Ф"`
	DeadlineDate   string  `json:"deadline_date" validate:"required" example:"2026-05-01"`
	DaysLeft       int32   `json:"days_left" validate:"required" example:"17"`
	RiskLevel      string  `json:"risk_level" validate:"required" example:"medium" enums:"low,medium,high"`
	AssignedTo     *int32  `json:"assigned_to,omitempty" example:"3"`
}

// RenewalsListResponse — ответ со списком продлений и общим количеством.
type RenewalsListResponse struct {
	Items []RenewalItem `json:"items" validate:"required"`
	Total int64         `json:"total" validate:"required" example:"42"`
}

// RenewalStats — агрегированная статистика для центра продлений.
type RenewalStats struct {
	Total      int32 `json:"total" validate:"required" example:"42"`
	Critical   int32 `json:"critical" validate:"required" example:"3"`
	Soon       int32 `json:"soon" validate:"required" example:"18"`
	Unassigned int32 `json:"unassigned" validate:"required" example:"7"`
}

// KanbanColumn — одна колонка канбана воронки «Подписка». kassa_ids перечисляет
// ID касс в этой колонке (в порядке fn_deadline ASC NULLS LAST).
type KanbanColumn struct {
	ID       int64   `json:"id" validate:"required" example:"54801221"`
	Name     string  `json:"name" validate:"required" example:"МЕНЕЕ 30 ДНЕЙ"`
	Sort     int32   `json:"sort_order" validate:"required" example:"10"`
	Color    string  `json:"color" validate:"required" example:"#fffeb2"`
	IsManual bool    `json:"is_manual" validate:"required" example:"false"`
	KassaIDs []int64 `json:"kassa_ids" validate:"required"`
}

// KanbanKassaCard — карточка кассы в канбане воронки «Подписка».
type KanbanKassaCard struct {
	ID                 int64   `json:"id" validate:"required" example:"18714699"`
	ClientID           *int64  `json:"client_id,omitempty" example:"18714699"`
	ClientName         string  `json:"client_name" validate:"required" example:"ООО Лидер"`
	KassaModel         string  `json:"kassa_model" validate:"required" example:"АТОЛ 25Ф"`
	InstallAddress     string  `json:"install_address" validate:"required" example:"г. Москва, ул. Ленина, 1"`
	FnDeadline         *string `json:"fn_deadline,omitempty" example:"2026-05-01"`
	StatusID           *int64  `json:"status_id,omitempty" example:"54801221"`
	LastFnExpiryStatus *string `json:"last_fn_expiry_status,omitempty" example:"delivered" enums:"sent,delivered,read,failed"`
}

// KanbanResponse — полный снимок канбана: колонки + карточки касс.
// kassas нормализованы отдельно, карточка рендерится один раз независимо
// от колонки (kassa.status_id определяет куда она попадёт).
type KanbanResponse struct {
	Columns []KanbanColumn    `json:"columns" validate:"required"`
	Kassas  []KanbanKassaCard `json:"kassas" validate:"required"`
}

// PaginatedResponse — обёртка для списков с пагинацией.
type PaginatedResponse[T any] struct {
	Data  []T   `json:"data" validate:"required"`
	Total int64 `json:"total" validate:"required"`
	Page  int   `json:"page" validate:"required"`
	Limit int   `json:"limit" validate:"required"`
}

// LoginRequest — запрос на авторизацию.
