import { createVuetify } from 'vuetify'
import '@mdi/font/css/materialdesignicons.css'
import 'vuetify/styles'
import '@/assets/design-tokens.css'

// KassaDesk V2 палитра. Light — primary, dark — следующей волной (R13).
// Hex-значения близки к Tailwind slate/blue/emerald/amber/rose, чтобы
// визуальный референс (KASSADESK_V2_VISUAL_REFERENCE_BEFORE_HEALTH_BARS.jsx)
// читался один-к-одному в Vuetify.
const lightTheme = {
  dark: false,
  colors: {
    background: '#F1F5F9',         // slate-100
    surface: '#FFFFFF',
    'surface-variant': '#F8FAFC',  // slate-50
    primary: '#2563EB',            // blue-600
    'primary-darken-1': '#1D4ED8', // blue-700
    secondary: '#64748B',          // slate-500
    accent: '#7C3AED',             // violet-600 (AI)
    success: '#10B981',            // emerald-500
    warning: '#F59E0B',            // amber-500
    error: '#F43F5E',              // rose-500
    info: '#3B82F6',               // blue-500
    'on-background': '#0F172A',    // slate-950
    'on-surface': '#0F172A',
  },
}

// Dark theme — обновлённая под slate-палитру R0 (F9 / R13). Background —
// slate-950 (#0F172A), surface — slate-800. Primary blue-400 для лучшего
// контраста на тёмном (blue-600 теряется). Status-цвета — на полтона ярче.
