package automation

import (
	"encoding/json"
	"strings"
	"testing"

	"github.com/jackc/pgx/v5/pgtype"
)

// Тест decodeActions: JSONB → []TriggerAction. Покрываем happy-path с SendTo + edge.
func TestDecodeActions(t *testing.T) {
	tests := []struct {
		name    string
		raw     string
		wantLen int
		check   func(t *testing.T, acts []TriggerAction)
	}{
		{
			name:    "send_template с primary_contact",
			// JSONB формат: ключ "type" (struct tag в TriggerAction.Type),
			// синхронизирован с UI/api schema. Не "action" — была опечатка
			// в первой версии теста, выявленная watchdog'ом.
			raw:     `[{"type":"send_template","template_id":42,"send_to":"primary_contact"}]`,
			wantLen: 1,
			check: func(t *testing.T, acts []TriggerAction) {
				if acts[0].Type != "send_template" {
					t.Errorf("Type got %q want send_template", acts[0].Type)
				}
				if acts[0].TemplateID != 42 {
					t.Errorf("TemplateID got %d want 42", acts[0].TemplateID)
				}
				if acts[0].SendTo != "primary_contact" {
					t.Errorf("SendTo got %q want primary_contact", acts[0].SendTo)
				}
			},
		},
		{
			name:    "send_template с all_contacts",
			raw:     `[{"type":"send_template","template_id":7,"send_to":"all_contacts"}]`,
			wantLen: 1,
			check: func(t *testing.T, acts []TriggerAction) {
				if acts[0].SendTo != "all_contacts" {
					t.Errorf("SendTo got %q want all_contacts", acts[0].SendTo)
				}
			},
		},
		{
			name:    "SendTo пустой → дефолт (primary в runtime)",
			raw:     `[{"type":"send_template","template_id":1}]`,
			wantLen: 1,
			check: func(t *testing.T, acts []TriggerAction) {
				if acts[0].SendTo != "" {
					t.Errorf("SendTo expected empty, got %q", acts[0].SendTo)
				}
			},
		},
		{
			name:    "empty JSONB → []",
			raw:     `[]`,
			wantLen: 0,
		},
		{
			name:    "nil raw → []",
			raw:     "",
			wantLen: 0,
		},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			var raw []byte
			if tc.raw != "" {
				raw = []byte(tc.raw)
			}
			acts, err := decodeActions(raw)
			if err != nil {
				t.Fatalf("decodeActions error: %v", err)
			}
			if len(acts) != tc.wantLen {
				t.Fatalf("len got %d want %d (acts=%+v)", len(acts), tc.wantLen, acts)
			}
			if tc.check != nil {
				tc.check(t, acts)
			}
		})
	}
}

// Тест JSON marshalling — обратное направление, чтобы settings UI сохранял
// корректный shape. SendTo с omitempty не должен попадать в JSON если пустой.
func TestTriggerAction_Marshal_OmitsEmptySendTo(t *testing.T) {
	a := TriggerAction{Type: "send_template", TemplateID: 5}
	b, err := json.Marshal(a)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	s := string(b)
	if strings.Contains(s, "send_to") {
		t.Errorf("send_to should be omitted when empty, got: %s", s)
	}
}

func TestTriggerAction_Marshal_IncludesSendTo(t *testing.T) {
	a := TriggerAction{Type: "send_template", TemplateID: 5, SendTo: "all_contacts"}
	b, err := json.Marshal(a)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	if !strings.Contains(string(b), `"send_to":"all_contacts"`) {
		t.Errorf("send_to=all_contacts expected in JSON, got: %s", string(b))
	}
}

// Тест interpolateTemplateText: подстановки переменных + поведение с пустыми
// датами (Valid:false). contact_name пробрасывается через args для loop'а в
// all_contacts (каждому target своё имя).
func TestInterpolateTemplateText(t *testing.T) {
	e := kassaCtx{
		ClientName:     "ООО Ромашка",
		ClientInn:      "1234567890",
		KassaModel:     "Атол 30Ф",
		InstallAddress: "г. Москва",
		FnDeadline:     pgtype.Timestamptz{Valid: false},
	}
	tmpl := "Здравствуйте, {{contact_name}}! Касса {{kassa_model}} в {{client_name}}, ИНН {{client_inn}}."
	got := interpolateTemplateText(tmpl, e, "Иван Иванов")
	want := "Здравствуйте, Иван Иванов! Касса Атол 30Ф в ООО Ромашка, ИНН 1234567890."
	if got != want {
