func TestInterpolateTemplateText_EmptyDeadlines(t *testing.T) {
	e := kassaCtx{
		ClientName: "ИП Петров",
		FnDeadline: pgtype.Timestamptz{Valid: false},
	}
	got := interpolateTemplateText("ФН до {{kassa_fn_deadline}}", e, "")
