package automation

// Date-based trigger executor.
//
// Работа:
//   1) Cron в 9:00 вызывает RunDateTriggers, итерируется по тенантам.
//   2) Для каждого enabled триггера по date_field вычисляется targetDate
//      = CURRENT_DATE - offset_days, подбираются сущности (kassa) с таким
//      значением в соответствующей колонке.
//   3) Для каждой сущности выполняются actions из JSONB.
//   4) Результат каждого action журналируется в automation_actions.
//
// Статусы сообщений:
//   send_failed           — Wazzup API отказал → сразу fallback-task
//   sent                  — Wazzup принял, ждём webhook
//   delivered             — webhook подтвердил (финал, OK)
//   delivery_failed       — webhook вернул failed → сразу fallback-task
//   timeout_not_delivered — sent > 24ч без delivered → fallback-task (CheckPendingActions)
//   task_created          — задача создана (финал, OK)

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"strings"
	"time"

	"bizprofit/internal/database"
	db "bizprofit/internal/database/db"

	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"
)

// WazzupSender — интерфейс для отправки (только те методы, которые нам нужны).
// Имплементируется *wazzup.Sender. Позволяет тестировать без реального клиента.
type WazzupSender interface {
	SendRaw(ctx context.Context, chatID, text, crmMessageID string) (messageID string, err error)
	NormalizePhone(raw string) string
	WithQueries(q *db.Queries) WazzupSender
	// IsEnabled возвращает false, когда AUTOMATION_SEND_ENABLED=false — в этом
	// случае триггер должен пропустить отправку и НЕ создавать fallback-task
	// (предполагается что amoCRM сам отправит сообщение по своим правилам).
	IsEnabled() bool
}


// TriggerAction — одна запись из JSONB поля actions.
type TriggerAction struct {
	Type string `json:"type" validate:"required"` // "send_template" | "create_task"

	// send_template
	TemplateID int32  `json:"template_id,omitempty"`
	Channel    string `json:"channel,omitempty"` // "wazzup"
	// SendTo — кому отправить шаблон (F3.5).
	// "primary_contact"  — основной контакт клиента (contact_links.is_primary=true).
	// "all_contacts"     — все активные контакты клиента (по одному сообщению на каждого).
	// "" (default)       — текущее поведение: первый найденный контакт (legacy fallback).
	// Применимо только при Type="send_template".
	SendTo string `json:"send_to,omitempty"`

	// create_task
	Title          string `json:"title,omitempty"`
	Priority       string `json:"priority,omitempty"` // "low"|"medium"|"high"
	Assignee       string `json:"assignee,omitempty"` // "responsible"|"admin"|"<user_id>"
	DueOffsetHours int32  `json:"due_offset_hours,omitempty"`
}

// kassaCtx — сжатый набор полей для выполнения действий.
type kassaCtx struct {
	ID                int64
	ClientID          pgtype.Int8
	ResponsibleUserID pgtype.Int8
	KassaModel        string
	InstallAddress    string
	FnDeadline        pgtype.Timestamptz
	OfdDeadline       pgtype.Date
	RegistrationDate  pgtype.Timestamptz
	ClientName        string
	ClientInn         string
}

// RunDateTriggers — основной вход из cron. Идёт по активным тенантам и
// обрабатывает каждый в отдельной транзакции (WithTenant).
func RunDateTriggers(ctx context.Context, queries *db.Queries, pool *pgxpool.Pool, sender WazzupSender) {
	if pool == nil {
		log.Println("DateTriggers: pool is nil, skipping")
		return
	}
	tenants, err := queries.ListActiveTenants(ctx)
	if err != nil {
		log.Printf("DateTriggers: failed to list tenants: %v", err)
		return
	}
	for _, t := range tenants {
		tenantID := t.ID
		err := database.WithTenant(ctx, pool, tenantID, func(q *db.Queries) error {
			return runForTenant(ctx, q, tenantID, sender)
		})
		if err != nil {
			log.Printf("DateTriggers: tenant %d failed: %v", tenantID, err)
		}
	}
}

func runForTenant(ctx context.Context, q *db.Queries, tenantID int32, sender WazzupSender) error {
	triggers, err := q.ListEnabledDateTriggers(ctx)
	if err != nil {
		return fmt.Errorf("list triggers: %w", err)
	}
	if len(triggers) == 0 {
		return nil
	}

	var totalExec int
	for _, tr := range triggers {
		entities, err := findEntitiesForTrigger(ctx, q, tr)
		if err != nil {
			log.Printf("DateTriggers: tenant %d, trigger %d (%s): find failed: %v", tenantID, tr.ID, tr.Name, err)
			continue
		}
		if len(entities) == 0 {
			continue
		}
		actions, err := decodeActions(tr.Actions)
		if err != nil {
			log.Printf("DateTriggers: tenant %d, trigger %d: bad actions JSON: %v", tenantID, tr.ID, err)
			continue
		}
		tenantSender := sender
		if tenantSender != nil {
			tenantSender = sender.WithQueries(q)
		}
		for _, e := range entities {
			for _, a := range actions {
				executeAction(ctx, q, tenantSender, tr, e, a)
				totalExec++
			}
		}
	}
	if totalExec > 0 {
		log.Printf("DateTriggers: tenant %d — executed %d actions", tenantID, totalExec)
	}
	return nil
}

// findEntitiesForTrigger — маршрутизирует по date_field, возвращает нормализованные kassaCtx.
func findEntitiesForTrigger(ctx context.Context, q *db.Queries, tr db.DateTrigger) ([]kassaCtx, error) {
	if tr.EntityType != "kassa" {
		return nil, nil
	}
	offset := tr.OffsetDays

	switch tr.DateField {
	case "fn_deadline":
		rows, err := q.FindKassasForTriggerFn(ctx, offset)
		if err != nil {
			return nil, err
		}
		out := make([]kassaCtx, 0, len(rows))
		for _, r := range rows {
			out = append(out, kassaCtx{
				ID: r.ID, ClientID: r.ClientID, ResponsibleUserID: r.ResponsibleUserID,
				KassaModel: r.KassaModel, InstallAddress: r.InstallAddress,
				FnDeadline: r.FnDeadline, ClientName: r.ClientName,
			})
		}
		return out, nil
	case "ofd_deadline":
		rows, err := q.FindKassasForTriggerOfd(ctx, offset)
		if err != nil {
			return nil, err
		}
		out := make([]kassaCtx, 0, len(rows))
		for _, r := range rows {
			out = append(out, kassaCtx{
				ID: r.ID, ClientID: r.ClientID, ResponsibleUserID: r.ResponsibleUserID,
				KassaModel: r.KassaModel, InstallAddress: r.InstallAddress,
				OfdDeadline: r.OfdDeadline, ClientName: r.ClientName,
			})
		}
		return out, nil
	case "registration_date":
		rows, err := q.FindKassasForTriggerReg(ctx, offset)
		if err != nil {
			return nil, err
		}
		out := make([]kassaCtx, 0, len(rows))
		for _, r := range rows {
			out = append(out, kassaCtx{
				ID: r.ID, ClientID: r.ClientID, ResponsibleUserID: r.ResponsibleUserID,
				KassaModel: r.KassaModel, InstallAddress: r.InstallAddress,
				RegistrationDate: r.RegistrationDate, ClientName: r.ClientName,
			})
		}
		return out, nil
	case "fn_expired_at":
		rows, err := q.FindKassasForTriggerExpired(ctx, offset)
		if err != nil {
			return nil, err
		}
		out := make([]kassaCtx, 0, len(rows))
		for _, r := range rows {
			out = append(out, kassaCtx{
				ID: r.ID, ClientID: r.ClientID, ResponsibleUserID: r.ResponsibleUserID,
				KassaModel: r.KassaModel, InstallAddress: r.InstallAddress,
				FnDeadline: r.FnDeadline, ClientName: r.ClientName,
			})
		}
		return out, nil
	}
	return nil, fmt.Errorf("unknown date_field %q", tr.DateField)
}

func decodeActions(raw []byte) ([]TriggerAction, error) {
	if len(raw) == 0 {
		return nil, nil
	}
	var out []TriggerAction
	if err := json.Unmarshal(raw, &out); err != nil {
		return nil, err
	}
	return out, nil
}

func executeAction(ctx context.Context, q *db.Queries, sender WazzupSender, tr db.DateTrigger, e kassaCtx, a TriggerAction) {
	switch a.Type {
	case "send_template":
		executeSendTemplate(ctx, q, sender, tr, e, a)
	case "create_task":
		executeCreateTask(ctx, q, tr, e, a)
	default:
		log.Printf("DateTriggers: trigger %d: unknown action type %q", tr.ID, a.Type)
	}
}

// ============================================================
// send_template
// ============================================================

func executeSendTemplate(ctx context.Context, q *db.Queries, sender WazzupSender, tr db.DateTrigger, e kassaCtx, a TriggerAction) {
	payload, _ := json.Marshal(a)

	// Kill-switch: если автоотправка выключена — amoCRM сам шлёт сообщения по своим
	// правилам, наша задача только залогировать факт "предполагаемой отправки" для
	// прозрачности. Fallback-task не создаём — избыточно.
	if sender == nil || !sender.IsEnabled() {
		insertActionLog(ctx, q, insertParams{
			TriggerID: tr.ID, EntityType: "kassa", EntityID: e.ID, ClientID: e.ClientID,
			ActionType: "send_template", Status: "skipped_amo",
			ErrorText: "автоотправка выключена — сообщение ожидается от amoCRM",
			Payload:   payload,
		})
		return
	}

	// 1. Найти шаблон
	templates, err := q.ListMessageTemplates(ctx)
	if err != nil {
		log.Printf("DateTriggers: trigger %d: list templates failed: %v", tr.ID, err)
		return
	}
	var tpl *db.MessageTemplate
	for i := range templates {
		if templates[i].ID == a.TemplateID {
			tpl = &templates[i]
			break
		}
	}
	if tpl == nil {
		log.Printf("DateTriggers: trigger %d: template %d not found", tr.ID, a.TemplateID)
		// Пишем провальный action, чтобы виден был админу.
		insertActionLog(ctx, q, insertParams{
			TriggerID: tr.ID, EntityType: "kassa", EntityID: e.ID, ClientID: e.ClientID,
			ActionType: "send_template", Status: "send_failed",
			ErrorText: fmt.Sprintf("template %d not found", a.TemplateID),
			Payload:   payload,
		})
		return
	}

	// 2. Найти контакт(ы) с телефоном. SendTo='all_contacts' → все активные
	// WhatsApp-готовые контакты клиента; иначе (primary_contact или пусто) —
	// один primary (через GetContactForWhatsApp).
	if !e.ClientID.Valid {
		insertActionLog(ctx, q, insertParams{
			TriggerID: tr.ID, EntityType: "kassa", EntityID: e.ID, ClientID: e.ClientID,
			ActionType: "send_template", Status: "send_failed",
			ErrorText: "kassa without client", Payload: payload,
		})
		return
	}

	type targetContact struct {
		id    int64
		name  string
		phone string
	}
	var targets []targetContact

	if a.SendTo == "all_contacts" {
		rows, listErr := q.ListContactsForWhatsApp(ctx, e.ClientID.Int64)
		if listErr != nil || len(rows) == 0 {
			actionID := insertActionLog(ctx, q, insertParams{
				TriggerID: tr.ID, EntityType: "kassa", EntityID: e.ID, ClientID: e.ClientID,
				ActionType: "send_template", Status: "send_failed",
				ErrorText: "no contacts with WhatsApp-ready phone", Payload: payload,
			})
			if actionID > 0 {
				createFallbackTask(ctx, q, actionID, "не отправлено", "нет контактов с WhatsApp-номером", tr, e, tpl)
			}
			return
		}
		for _, row := range rows {
			phone := strings.TrimSpace(row.WhatsappNumber)
			if phone == "" {
				continue
			}
			targets = append(targets, targetContact{id: row.ID, name: row.Name.String, phone: phone})
		}
	} else {
		contact, oneErr := q.GetContactForWhatsApp(ctx, e.ClientID.Int64)
		if oneErr != nil {
			log.Printf("DateTriggers: trigger %d: no contact with WhatsApp for client %d: %v", tr.ID, e.ClientID.Int64, oneErr)
			actionID := insertActionLog(ctx, q, insertParams{
				TriggerID: tr.ID, EntityType: "kassa", EntityID: e.ID, ClientID: e.ClientID,
				ActionType: "send_template", Status: "send_failed",
				ErrorText: "no contact with WhatsApp-ready phone", Payload: payload,
			})
			if actionID > 0 {
				createFallbackTask(ctx, q, actionID, "не отправлено", "нет контакта с WhatsApp-номером", tr, e, tpl)
			}
			return
		}
		phone := strings.TrimSpace(contact.WhatsappNumber)
		if phone == "" {
			actionID := insertActionLog(ctx, q, insertParams{
				TriggerID: tr.ID, EntityType: "kassa", EntityID: e.ID, ClientID: e.ClientID,
				ActionType: "send_template", Status: "send_failed",
				ErrorText: "contact phone empty", Payload: payload,
			})
			if actionID > 0 {
				createFallbackTask(ctx, q, actionID, "не отправлено", "у контакта пустой телефон", tr, e, tpl)
			}
			return
		}
		targets = append(targets, targetContact{id: contact.ID, name: contact.Name.String, phone: phone})
	}

	// 3. Отправить каждому target'у (для primary — один итератор, для all — все).
	for i, t := range targets {
		text := interpolateTemplateText(tpl.Text, e, t.name)

		actionID := insertActionLog(ctx, q, insertParams{
			TriggerID: tr.ID, EntityType: "kassa", EntityID: e.ID, ClientID: e.ClientID,
			ActionType: "send_template", Status: "sent", Payload: payload,
		})
		if actionID == 0 {
			continue
		}

		if sender == nil {
			updateActionFailed(ctx, q, actionID, "wazzup sender not configured")
			createFallbackTask(ctx, q, actionID, "не отправлено", "Wazzup не настроен", tr, e, tpl)
			continue
		}
		chatID := sender.NormalizePhone(t.phone)
		if chatID == "" {
			updateActionFailed(ctx, q, actionID, "phone normalization failed")
			createFallbackTask(ctx, q, actionID, "не отправлено", "не удалось нормализовать телефон", tr, e, tpl)
			continue
		}
		// crmMsgID — детерминирован (trigger+kassa+date+contact-index), чтобы
		// retry не задвоил отправку в Wazzup при повторном вызове в тот же день.
		crmMsgID := fmt.Sprintf("bizprofit-trigger%d-kassa%d-%s-c%d", tr.ID, e.ID, time.Now().Format("2006-01-02"), i)
		msgID, sendErr := sender.SendRaw(ctx, chatID, text, crmMsgID)
		if sendErr != nil {
			updateActionFailed(ctx, q, actionID, sendErr.Error())
			createFallbackTask(ctx, q, actionID, "не отправлено", sendErr.Error(), tr, e, tpl)
			continue
		}
		_ = q.UpdateAutomationActionStatus(ctx, db.UpdateAutomationActionStatusParams{
			ID:              actionID,
			Status:          "sent",
			ErrorText:       pgtype.Text{},
			WazzupMessageID: pgtype.Text{String: msgID, Valid: msgID != ""},
		})
	}
}

func updateActionFailed(ctx context.Context, q *db.Queries, actionID int64, errText string) {
	_ = q.UpdateAutomationActionStatus(ctx, db.UpdateAutomationActionStatusParams{
		ID:        actionID,
		Status:    "send_failed",
		ErrorText: pgtype.Text{String: errText, Valid: errText != ""},
	})
}

// ============================================================
// create_task
// ============================================================

func executeCreateTask(ctx context.Context, q *db.Queries, tr db.DateTrigger, e kassaCtx, a TriggerAction) {
	payload, _ := json.Marshal(a)

	title := strings.TrimSpace(a.Title)
	if title == "" {
		title = "Задача по триггеру: " + tr.Name
	}
	priority := mapPriority(a.Priority)
	assignedTo := resolveAssignee(ctx, q, a.Assignee, e.ResponsibleUserID)
	createdBy := int32(1)
	if assignedTo.Valid {
		createdBy = assignedTo.Int32
	}

	var dueDate pgtype.Date
	if a.DueOffsetHours != 0 {
		dueDate = pgtype.Date{Time: time.Now().Add(time.Duration(a.DueOffsetHours) * time.Hour), Valid: true}
	}

	descParts := []string{}
	if tr.Name != "" {
		descParts = append(descParts, "Триггер: "+tr.Name)
	}
	if e.KassaModel != "" {
		descParts = append(descParts, "Касса: "+e.KassaModel)
	}
	if e.InstallAddress != "" {
		descParts = append(descParts, "Адрес: "+e.InstallAddress)
	}
	description := strings.Join(descParts, "\n")

	task, err := q.CreateTask(ctx, db.CreateTaskParams{
		Title:       title,
		Description: description,
		DueDate:     dueDate,
		Priority:    priority,
		AssignedTo:  assignedTo,
		CreatedBy:   createdBy,
		ClientID:    e.ClientID,
		KassaID:     pgtype.Int8{Int64: e.ID, Valid: true},
		Source:      fmt.Sprintf("date_trigger_%d", tr.ID),
		Status:      "todo",
	})
	if err != nil {
