func mapPriority(s string) int32 {
	switch strings.ToLower(strings.TrimSpace(s)) {
	case "low":
		return 1
	case "medium", "med":
		return 2
	case "high", "urgent":
		return 3
	default:
		return 2
	}
}

// resolveAssignee — "responsible" → пользователь кассы (через amo_user_id),
// "admin" → user id 1, "<число>" → прямое значение.
func resolveAssignee(ctx context.Context, q *db.Queries, assignee string, responsible pgtype.Int8) pgtype.Int4 {
	a := strings.ToLower(strings.TrimSpace(assignee))
	if a == "" || a == "responsible" {
		if responsible.Valid {
			if id, err := q.FindUserByAmoId(ctx, responsible); err == nil {
				return pgtype.Int4{Int32: id, Valid: true}
			}
			if responsible.Int64 > 0 && responsible.Int64 <= 10000 {
				return pgtype.Int4{Int32: int32(responsible.Int64), Valid: true}
			}
		}
		return pgtype.Int4{Int32: 1, Valid: true}
	}
	if a == "admin" {
		return pgtype.Int4{Int32: 1, Valid: true}
	}
	// числовой ID
	var n int32
	if _, err := fmt.Sscanf(a, "%d", &n); err == nil && n > 0 {
		return pgtype.Int4{Int32: n, Valid: true}
	}
	return pgtype.Int4{Int32: 1, Valid: true}
}

