// createFallbackTaskFromAction — вариант, где мы знаем только automation_action.
// Повторно подгружает контекст кассы из БД.
func createFallbackTaskFromAction(ctx context.Context, q *db.Queries, a automationActionCommon, reason, details string) int64 {
	e, ok := loadKassaCtx(ctx, q, a.EntityType, a.EntityID)
	if !ok {
		log.Printf("DateTriggers: fallback: entity %s/%d not found", a.EntityType, a.EntityID)
		return 0
	}
	var tr db.DateTrigger
	if a.TriggerID.Valid {
		if row, err := q.GetDateTrigger(ctx, a.TriggerID.Int64); err == nil {
			tr = db.DateTrigger{
				ID:         row.ID,
				TenantID:   row.TenantID,
				Name:       row.Name,
				EntityType: row.EntityType,
				DateField:  row.DateField,
				OffsetDays: row.OffsetDays,
				Actions:    row.Actions,
				Enabled:    row.Enabled,
				CreatedAt:  row.CreatedAt,
				UpdatedAt:  row.UpdatedAt,
			}
		}
	}
	var tpl *db.MessageTemplate
	if a.ActionType == "send_template" {
		if id := templateIDFromPayload(a.Payload); id > 0 {
			all, err := q.ListMessageTemplates(ctx)
			if err == nil {
				for i := range all {
					if all[i].ID == id {
						tpl = &all[i]
						break
					}
				}
			}
		}
	}
	return createFallbackTask(ctx, q, a.ID, reason, details, tr, e, tpl)
}

func templateIDFromPayload(raw []byte) int32 {
	if len(raw) == 0 {
		return 0
	}
	var a TriggerAction
	_ = json.Unmarshal(raw, &a)
	return a.TemplateID
}

func loadKassaCtx(ctx context.Context, q *db.Queries, entityType string, entityID int64) (kassaCtx, bool) {
	if entityType != "kassa" {
		return kassaCtx{}, false
	}
	row, err := q.GetKassaContextForAction(ctx, entityID)
	if err != nil {
		return kassaCtx{}, false
	}
	return kassaCtx{
		ID: row.ID, ClientID: row.ClientID, ResponsibleUserID: row.ResponsibleUserID,
		KassaModel: row.KassaModel, InstallAddress: row.InstallAddress,
		FnDeadline: row.FnDeadline, OfdDeadline: row.OfdDeadline,
		RegistrationDate: row.RegistrationDate,
		ClientName:       row.ClientName, ClientInn: row.ClientInn,
	}, true
}

func statusForFallback(reason string) string {
	switch reason {
	case "не отправлено":
		return "send_failed"
	case "не доставлено":
		return "delivery_failed"
	case "не доставлено (тайм-аут)":
		return "timeout_not_delivered"
	default:
		return "send_failed"
	}
}

