func interpolateTemplateText(tmpl string, e kassaCtx, contactName string) string {
	fnDeadline := ""
	if e.FnDeadline.Valid {
		fnDeadline = e.FnDeadline.Time.Format("02.01.2006")
	}
	ofdDeadline := ""
	if e.OfdDeadline.Valid {
		ofdDeadline = e.OfdDeadline.Time.Format("02.01.2006")
	}
	regDate := ""
	if e.RegistrationDate.Valid {
		regDate = e.RegistrationDate.Time.Format("02.01.2006")
	}
	pairs := []string{
		"{{client_name}}", e.ClientName,
		"{{contact_name}}", contactName,
		"{{kassa_model}}", e.KassaModel,
		"{{kassa_address}}", e.InstallAddress,
		"{{kassa_fn_deadline}}", fnDeadline,
		"{{kassa_ofd_deadline}}", ofdDeadline,
		"{{kassa_registration_date}}", regDate,
		"{{client_inn}}", e.ClientInn,
		"{client_name}", e.ClientName,
		"{contact_name}", contactName,
		"{kassa_model}", e.KassaModel,
		"{install_address}", e.InstallAddress,
		"{fn_deadline}", fnDeadline,
		"{ofd_deadline}", ofdDeadline,
	}
	return strings.NewReplacer(pairs...).Replace(tmpl)
}

