import { defineStore } from 'pinia'
import { getProfileMeUiPrefs, patchProfileMeUiPrefs } from "@/api/generated";

interface ClientTab {
  id: string
  name: string
  lastRoute: string
}

// UI prefs хранятся per-user в users.ui_preferences JSONB на бэке.
// Frontend держит локальную копию, делает merge и шлёт debounced PATCH.
export interface UIPrefs {
  open_clients_mode?: 'tabs' | 'list'
  sidebar_layout?: string[]           // порядок пунктов меню (F1 follow-up)
  client_card_layout?: string[]       // порядок блоков в карточке клиента (F1 follow-up)
  dashboard_widgets?: string[]        // видимые виджеты на Dashboard (F1 follow-up)
  visible_sections?: string[]         // секции «Наша компания» (F7.2)
}

const HINTS_STORAGE_KEY = 'bp.hintsEnabled'

function loadHintsEnabled(): boolean {
  const raw = localStorage.getItem(HINTS_STORAGE_KEY)
  if (raw === null) return true
  return raw === '1'
}

export const useAppStore = defineStore('app', {
  state: () => ({
    clientTabs: JSON.parse(sessionStorage.getItem('clientTabs') || '[]') as ClientTab[],
    hintsEnabled: loadHintsEnabled(),
    uiPrefs: {} as UIPrefs,
    uiPrefsLoaded: false,
  }),
  getters: {
    openClientsMode(): 'tabs' | 'list' {
      return this.uiPrefs.open_clients_mode ?? 'tabs'
    },
  },
  actions: {
    openTab(id: string, name: string, lastRoute?: string) {
      const existing = this.clientTabs.find(t => t.id === id)
      if (existing) {
        existing.name = name
        if (lastRoute) existing.lastRoute = lastRoute
      } else {
        this.clientTabs.push({ id, name, lastRoute: lastRoute || `/clients/${id}` })
      }
      this._persist()
    },
    updateTabRoute(clientId: string, route: string) {
      const tab = this.clientTabs.find(t => t.id === clientId)
      if (tab) {
        tab.lastRoute = route
        this._persist()
      }
    },
    closeTab(id: string) {
      this.clientTabs = this.clientTabs.filter(t => t.id !== id)
      this._persist()
    },
    setHintsEnabled(value: boolean) {
      this.hintsEnabled = value
      localStorage.setItem(HINTS_STORAGE_KEY, value ? '1' : '0')
    },
    toggleHints() {
      this.setHintsEnabled(!this.hintsEnabled)
    },

    async loadUIPrefs() {
      if (this.uiPrefsLoaded) return
      const { data } = await getProfileMeUiPrefs()
      if (data?.prefs) {
        this.uiPrefs = data.prefs as UIPrefs
      }
      this.uiPrefsLoaded = true
    },

    async updateUIPrefs(patch: Partial<UIPrefs>) {
      this.uiPrefs = { ...this.uiPrefs, ...patch }
      await patchProfileMeUiPrefs({ body: { prefs: this.uiPrefs as unknown as Record<string, never> } })
    },

    _persist() {
      sessionStorage.setItem('clientTabs', JSON.stringify(this.clientTabs))
    },
  },
})

