const base = vuetify()

// Дополнительные правила поверх vuetify-preset: запреты на регрессию
// типизированного API-клиента (см. .github/workflows/swagger-gate.yml).
// CI gate ловит факт раз в PR, ESLint ловит локально в IDE по мере
// набора кода — двойной заслон.
const apiDiscipline = {
  files: ['src/**/*.{ts,vue}'],
  ignores: [
    // Исключения — точки, где runtime обращается к низкоуровневой обвязке.
    'src/api/generated/**',
    'src/api/runtime.ts',
    'src/api/download.ts',
    // chat-store держит WebSocket-инициализацию: URL `/api/chat/ws` через
    // window.WebSocket(), это не HTTP fetch, паттерн другой.
    'src/stores/chat.ts',
  ],
  rules: {
    'no-restricted-syntax': [
      'error',
      {
        // fetch('/api/...') и fetch(`/api/...`) — обход типизированного SDK.
        // Используем @/api/generated. Если эндпоинт реально не покрыт swagger —
        // добавить аннотации на backend handler и `npm run generate:api`.
        selector: "CallExpression[callee.name='fetch'] > Literal[value=/^\\/api\\//]",
        message: 'Запрещено: raw fetch к /api. Используй сгенерированный клиент из @/api/generated.',
