      {
        // Старый openapi-fetch client (client.GET('/path', ...)). Файл
        // удалён в Wave C, импорт ловится по специфичному литералу пути.
        selector: "ImportDeclaration[source.value='@/api/client']",
        message: 'Запрещено: @/api/client удалён в Wave API-CLIENT-C. Импорт из @/api/generated.',
      },
    ],
  },
}

export default [...base, apiDiscipline]

