        for (i, &l) in logits.iter().enumerate() {
            if i == 2 || i == 5 || i == 7 {
                assert!(l.is_finite(), "token {i} should be allowed");
            } else {
                assert!(
                    l == f32::NEG_INFINITY,
                    "token {i} should be masked, got {l}"
                );
            }
        }
