    }

    #[cfg(feature = "xgrammar")]
    #[tokio::test]
    async fn async_compile_regex() {
        let compiler = make_compiler();
        let result = compiler
            .compile(StructuredOutputOption::Regex, "[a-z]+")
            .await;
        assert!(result.is_ok());
    }

    #[cfg(feature = "xgrammar")]
    #[tokio::test]
    async fn async_compile_caches() {
        let compiler = make_compiler();

        // First compilation
        let r1 = compiler
            .compile(StructuredOutputOption::Regex, "[0-9]+")
            .await;
        assert!(r1.is_ok());

