                    "error must point at the missing feature: {msg}"
                );
            }
        }
    }

    #[test]
    fn hash_spec_different_options() {
        let h1 = hash_spec(&StructuredOutputOption::Regex, "abc");
        let h2 = hash_spec(&StructuredOutputOption::Grammar, "abc");
        assert_ne!(h1, h2);
    }

    #[test]
    fn hash_spec_different_specs() {
        let h1 = hash_spec(&StructuredOutputOption::Regex, "abc");
        let h2 = hash_spec(&StructuredOutputOption::Regex, "def");
        assert_ne!(h1, h2);
    }

    #[test]
    fn hash_spec_same_is_deterministic() {
        let h1 = hash_spec(&StructuredOutputOption::Regex, "test");
        let h2 = hash_spec(&StructuredOutputOption::Regex, "test");
        assert_eq!(h1, h2);
    }

    // ─── xgrammar end-to-end (Bug 10 regression coverage) ──────────
    //
    // Goes through the full vllm-rust compile dispatch under the
    // `xgrammar` feature, builds a byte-level synthetic vocab, and
    // verifies that the user's reproducer schema enforces:
    //   - `additionalProperties: false`
    //   - `minimum` / `maximum` on integers
    //   - `minLength` / `maxLength` on strings
    //   - no markdown bytes (`*`) anywhere at the start
    //
    // Mirrors `/tmp/grammar_strictness_check.py` at the API surface
    // immediately upstream of the HTTP layer.

    #[cfg(feature = "xgrammar")]
    fn byte_level_compiler() -> GrammarCompiler {
        let vocab: Vec<Vec<u8>> = (0u32..256).map(|b| vec![b as u8]).collect();
        let vi = Arc::new(VocabularyIndex::from_token_bytes(vocab));
        GrammarCompiler::new(vi)
    }

    #[cfg(feature = "xgrammar")]
    #[test]
    fn xgrammar_compile_strictness_reproducer_via_vllm_rust() {
        // Exactly the schema in /tmp/grammar_strictness_check.py.
        let schema = r#"{
            "type":"object",
            "additionalProperties":false,
            "required":["foo","bar"],
            "properties":{
                "foo":{"type":"integer","minimum":1,"maximum":1000},
                "bar":{"type":"string","minLength":3,"maxLength":50}
            }
        }"#;
        let compiler = byte_level_compiler();
        let grammar = compiler
            .compile_sync(&StructuredOutputOption::JsonSchema, schema)
            .expect("xgrammar compile via vllm-rust dispatch");

        // At the very first decode step we must allow `{` and reject
        // any markdown-emphasis bytes — that's the bug repro.
        let mut bm = crate::sampling::grammar::PackedBitmask::new(1, 256);
        grammar.fill_bitmask(&mut bm, 0);

        let allowed = |id: usize| bm.get_bit(0, id);
        assert!(allowed(b'{' as usize), "first byte: '{{' must be allowed");
        assert!(
            !allowed(b'*' as usize),
            "'*' (markdown emphasis) must be rejected at start of object"
        );
        assert!(
            !allowed(b'a' as usize),
            "letter 'a' must be rejected at start of object"
        );
        // is_terminated must be false at start
        assert!(!grammar.is_terminated());
    }

    #[cfg(feature = "xgrammar")]
    #[test]
    fn xgrammar_dispatch_uses_cached_compiler_across_compiles() {
        // Two independent compiles share the same xgrammar
        // GrammarCompiler instance (and therefore its internal
        // schema-hash cache + tokenizer marshal). Verified by the
        // OnceLock seam in `GrammarCompiler::xgrammar_compiler_handle`.
        let compiler = byte_level_compiler();
        let _a = compiler
            .compile_sync(&StructuredOutputOption::JsonSchema, r#"{"type":"integer"}"#)
            .unwrap();
        let _b = compiler
            .compile_sync(&StructuredOutputOption::JsonSchema, r#"{"type":"string"}"#)
            .unwrap();
        // No assertion beyond "both compile without panic" — the
        // OnceLock contract guarantees both calls used the same
        // upstream xgrammar compiler; we cover that in the unit
        // tests of xgrammar-rs.
    }

    // ── Bug 10-v1.6 regression: nested-schema enforcement via EBNF ──
    //
    // The concept_test schema from /tmp/raw_output_probe.py exposed
    // two xgrammar CompileJSONSchema bugs that were verified in
    // xgrammar-rs/tests/nested_strictness.rs. Phase 3 routes such
    // schemas through `schema_to_ebnf` + `compile_ebnf` to bypass
    // those bugs. This test asserts the dispatch reaches the EBNF
    // path AND that the resulting matcher actually enforces the
    // failing constraints.

    #[cfg(feature = "xgrammar")]
    fn byte_level_compiler_256() -> GrammarCompiler {
        let vocab: Vec<Vec<u8>> = (0u32..256).map(|b| vec![b as u8]).collect();
        let vi = Arc::new(VocabularyIndex::from_token_bytes(vocab));
        GrammarCompiler::new(vi)
    }

    #[cfg(feature = "xgrammar")]
    const CONCEPT_SCHEMA: &str = r##"{
        "type":"object","additionalProperties":false,
        "required":["unique_features","description","year","season"],
        "properties":{
            "unique_features":{"type":"array","minItems":5,"maxItems":7,
                "items":{"type":"string","pattern":"^[А-Яа-яЁё0-9 ,.!?;:\\-—«»()…\\\"'\\n]+$","minLength":8,"maxLength":80}},
            "description":{"type":"string","pattern":"^[А-Яа-яЁё0-9 ,.!?;:\\-—«»()…\\\"'\\n]+$","minLength":300,"maxLength":1600},
            "year":{"type":"integer","minimum":1,"maximum":9999},
            "season":{"type":"string","enum":["spring","summer","autumn","winter"]}
        }
    }"##;

    #[cfg(feature = "xgrammar")]
    fn min_features_array() -> Vec<u8> {
        let item = "\"привет1234\"".as_bytes();
        let mut out = Vec::new();
        out.push(b'[');
        for i in 0..5 {
            if i > 0 {
                out.push(b',');
            }
            out.extend_from_slice(item);
        }
        out.push(b']');
        out
    }

    #[cfg(feature = "xgrammar")]
    fn cyr_repeat(target_bytes: usize) -> Vec<u8> {
        let mut out = Vec::with_capacity(target_bytes + 4);
        while out.len() < target_bytes {
            out.extend_from_slice("ы".as_bytes());
        }
        out
    }

    #[cfg(feature = "xgrammar")]
    #[test]
    fn xgrammar_ebnf_path_enforces_minlength_inside_string() {
        // T1 equivalent from xgrammar-rs/tests/nested_strictness.rs:
        // after the empty-description opening quote, the closing quote
        // must be REJECTED because minLength=300 is not satisfied. The
        // EBNF path enforces this; the direct CompileJSONSchema does not.
        let compiler = byte_level_compiler_256();
        let mut grammar = compiler
            .compile_sync(&StructuredOutputOption::JsonSchema, CONCEPT_SCHEMA)
            .expect("compile concept schema via EBNF dispatch");

        // Feed the prefix that lands at "after `\"description\":\"`".
        let mut prefix = Vec::new();
        prefix.extend_from_slice(b"{\"unique_features\":");
        prefix.extend_from_slice(&min_features_array());
        prefix.extend_from_slice(b",\"description\":\"");
        let tokens: Vec<u32> = prefix.iter().map(|&b| b as u32).collect();
        assert!(
            grammar.accept_tokens(&tokens),
            "prefix should be acceptable up to the description opening quote"
        );

        let mut bm = crate::sampling::grammar::PackedBitmask::new(1, 256);
        grammar.fill_bitmask(&mut bm, 0);
        assert!(
            !bm.get_bit(0, b'"' as usize),
            "T1 regression: closing-quote allowed at empty-description position — \
             EBNF path must enforce minLength=300"
        );
    }

    #[cfg(feature = "xgrammar")]
    #[test]
    fn xgrammar_ebnf_path_enforces_key_boundary_strictness() {
        // T6 equivalent: after `\",` between description and the next
        // required key, only ASCII `"` must open the next key — byte
        // 0xE2 (start of U+201C `\u{201c}`) must be REJECTED.
        let compiler = byte_level_compiler_256();
        let mut grammar = compiler
            .compile_sync(&StructuredOutputOption::JsonSchema, CONCEPT_SCHEMA)
            .expect("compile concept schema via EBNF dispatch");

        let mut prefix = Vec::new();
        prefix.extend_from_slice(b"{\"unique_features\":");
        prefix.extend_from_slice(&min_features_array());
        prefix.extend_from_slice(b",\"description\":\"");
        prefix.extend_from_slice(&cyr_repeat(700));
        prefix.extend_from_slice(b"\",");
        let tokens: Vec<u32> = prefix.iter().map(|&b| b as u32).collect();
        assert!(
            grammar.accept_tokens(&tokens),
            "valid prefix up to key-boundary should be accepted"
        );

        let mut bm = crate::sampling::grammar::PackedBitmask::new(1, 256);
        grammar.fill_bitmask(&mut bm, 0);
        assert!(
            bm.get_bit(0, b'"' as usize),
            "sanity: ASCII `\"` must still be allowed at key-start"
        );
        assert!(
            !bm.get_bit(0, 0xE2),
            "T6 regression: 0xE2 (typographic-quote start) allowed at key-boundary — \
             EBNF path must enforce strict key alternation"
        );
    }
}

//! `StructuredOutputGrammar` adapter backed by upstream xgrammar
//! (mlc-ai/xgrammar) via the `xgrammar-rs` FFI crate.
//!
//! Provides full JSON Schema / regex / EBNF enforcement at parity
//! with the Python xgrammar library used by upstream vLLM. Replaces
//! the partial native Rust port at `super::json_schema` for the
//! JSON-Schema path when the `xgrammar` feature is enabled.
//!
//! ## Vocabulary mapping (known gap)
//!
//! [`super::vocabulary::VocabularyIndex`] decodes each token through
//! the HF tokenizer's `decode` method, yielding plain UTF-8 bytes.
//! That maps cleanly to xgrammar's `VocabType::Raw`. For Qwen3 /
//! Llama / Mistral families this is sufficient because their
//! tokenizers never split a single Unicode codepoint across two
//! tokens, so every token has a stable decoded form.
//!
//! For tokenizers that DO split codepoints (some older SentencePiece
//! variants), this routing would silently allow the matcher to
//! accept "valid" byte sequences that the tokenizer then emits as
//! invalid UTF-8. Tracking work: switch the bridge to consume the
//! tokenizer's raw BPE byte alphabet (`tokenizer.get_vocab()`) and
//! pick the matching `VocabType` family per detection. Documented in
//! the build-vocab path below as a TODO.

use std::sync::{Arc, Mutex};

use anyhow::Context;

use super::vocabulary::VocabularyIndex;
use super::{PackedBitmask, StructuredOutputGrammar};

/// Pick the xgrammar `VocabType` for a vocabulary.
///
/// 1. Manual override wins: `VLLM_XGRAMMAR_VOCAB_TYPE=raw|byte_fallback|byte_level`
///    (case-insensitive). Unknown values are ignored with a warn-log.
/// 2. Heuristic auto-detect on the decoded bytes that
///    [`VocabularyIndex`] already exposes:
///    - `<0xNN>` SentencePiece byte-fallback markers ⇒ `ByteFallback`
///    - `Ġ` (U+0120) / `Ċ` (U+010A) HF BPE byte-alphabet glyphs ⇒ `ByteLevel`
///    - otherwise ⇒ `Raw` (Qwen / GPT-OSS / most modern decoded BPE)
///
/// **Known gap (documented):** for SentencePiece tokenizers whose
/// `decode([id])` already resolves byte-fallback markers into raw
/// bytes (Llama/Mistral with HF tokenizers crate), the marker pattern
/// isn't visible in the decoded vocab — detection lands on Raw and
/// we emit a WARN-log to surface the gap. The proper fix is to
/// consume the tokenizer's raw form via `tokenizer.get_vocab()`,
/// which is an architectural change to [`VocabularyIndex`]. Tracked
/// as a follow-up; for now, operators can set the env override.
pub(crate) fn detect_vocab_type(vocab: &VocabularyIndex) -> xgrammar_rs::VocabType {
    if let Ok(raw) = std::env::var("VLLM_XGRAMMAR_VOCAB_TYPE") {
        match raw.trim().to_ascii_lowercase().as_str() {
            "raw" => return xgrammar_rs::VocabType::Raw,
            "byte_fallback" | "bytefallback" => return xgrammar_rs::VocabType::ByteFallback,
            "byte_level" | "bytelevel" => return xgrammar_rs::VocabType::ByteLevel,
            other => {
                tracing::warn!(
                    target: "vllm_core::xgrammar",
                    value = %other,
                    "VLLM_XGRAMMAR_VOCAB_TYPE has unknown value (allowed: raw, byte_fallback, byte_level); falling through to auto-detect"
                );
            }
        }
    }

    let mut saw_sp_marker = false;
    let mut saw_bpe_marker = false;
    let mut non_ascii_count: usize = 0;
    let mut sample_count: usize = 0;

    for (_id, bytes) in vocab.iter() {
        if bytes.is_empty() {
            continue;
        }
        sample_count += 1;
        // Cheap byte-window scan first — both markers are short.
        // SentencePiece byte-fallback tokens are exactly "<0xNN>" —
        // 6 ASCII bytes, easy substring match.
        if bytes.len() == 6
            && bytes[0] == b'<'
            && bytes[1] == b'0'
            && bytes[2] == b'x'
            && bytes[5] == b'>'
            && bytes[3].is_ascii_hexdigit()
            && bytes[4].is_ascii_hexdigit()
        {
            saw_sp_marker = true;
        }
        // HF BPE byte alphabet: any token starting with U+0120 (Ġ,
        // UTF-8 = 0xC4 0xA0) or U+010A (Ċ, UTF-8 = 0xC4 0x8A).
        if bytes.len() >= 2 && bytes[0] == 0xC4 && (bytes[1] == 0xA0 || bytes[1] == 0x8A) {
            saw_bpe_marker = true;
        }
        // Track non-ASCII byte fraction so we can flag suspicious
        // "all-ASCII vocab" decisions below.
        if bytes.iter().any(|&b| b >= 0x80) {
            non_ascii_count += 1;
        }
    }

    if saw_sp_marker {
        return xgrammar_rs::VocabType::ByteFallback;
    }
    if saw_bpe_marker {
        return xgrammar_rs::VocabType::ByteLevel;
    }

    // Fell through to Raw. If the vocab looks suspiciously
    // ASCII-only (< 5% tokens with high-bit bytes) on a non-trivial
    // sample, the model is probably SentencePiece-family with
    // already-resolved byte-fallback — warn the operator to set
    // the override.
    if sample_count >= 1024 {
        let frac = non_ascii_count as f64 / sample_count as f64;
        if frac < 0.05 {
            tracing::warn!(
                target: "vllm_core::xgrammar",
                non_ascii_fraction = frac,
                sample_count,
                "xgrammar vocab-type auto-detect landed on Raw with very low non-ASCII fraction. \
                 If this is a SentencePiece family model (Llama/Mistral/Mixtral), set \
                 VLLM_XGRAMMAR_VOCAB_TYPE=byte_fallback to enforce grammars correctly."
            );
        }
    }
    xgrammar_rs::VocabType::Raw
}

/// Build an xgrammar `TokenizerInfo` from our `VocabularyIndex`.
/// Cached at `crate::sampling::grammar::compiler::GrammarCompiler`
/// level so the marshal cost is paid once per engine init, not per
/// request.
///
/// Routing:
///   - If the `VocabularyIndex` carries a `raw_token_bytes` view
///     (built from `tokenizer.get_vocab()`), pass those raw byte
///     strings + `VocabType::ByteLevel`. xgrammar then maps the BPE
///     byte-alias chars (`Ġ`/`Ċ`/etc.) back to grammar bytes and
///     correctly enforces multi-byte BPE tokens against the grammar.
///   - Otherwise (synthetic vocab built via `from_token_bytes`),
///     pass the decoded form + heuristic `detect_vocab_type`.
///
/// The env override `VLLM_XGRAMMAR_VOCAB_TYPE` still wins over both.
pub(crate) fn tokenizer_info_from_vocab(
    vocab: &VocabularyIndex,
    stop_token_ids: &[u32],
) -> anyhow::Result<Arc<xgrammar_rs::TokenizerInfo>> {
    // Env override takes precedence (and uses the decoded form, since
    // operators setting the env explicitly know what they want).
    let env_override = std::env::var("VLLM_XGRAMMAR_VOCAB_TYPE").ok();

    let (encoded, vocab_type) = match (env_override.as_deref(), vocab.raw_token_bytes_iter()) {
        // Operator-forced type — use decoded form.
        (Some(_), _) => {
            let enc: Vec<Vec<u8>> = vocab.iter().map(|(_, b)| b.to_vec()).collect();
            (enc, detect_vocab_type(vocab))
        }
        // Raw HF vocab available → ByteLevel path.
        (None, Some(raw_iter)) => {
            let enc: Vec<Vec<u8>> = raw_iter.map(|(_, b)| b.to_vec()).collect();
            (enc, xgrammar_rs::VocabType::ByteLevel)
        }
        // No raw vocab and no override → decoded + heuristic.
        (None, None) => {
            let enc: Vec<Vec<u8>> = vocab.iter().map(|(_, b)| b.to_vec()).collect();
            (enc, detect_vocab_type(vocab))
        }
    };

    tracing::info!(
        target: "vllm_core::xgrammar",
        ?vocab_type,
        vocab_size = vocab.vocab_size(),
        source = if vocab.raw_token_bytes_iter().is_some() && env_override.is_none() {
            "raw_hf_vocab"
        } else {
            "decoded_per_token"
        },
        "xgrammar TokenizerInfo built"
    );

    let info = xgrammar_rs::TokenizerInfo::from_encoded_vocab(
        &encoded,
        vocab_type,
        /* add_prefix_space = */ false,
        stop_token_ids,
    )
    .context("xgrammar TokenizerInfo::from_encoded_vocab")?;
    Ok(Arc::new(info))
}

/// Convenience: build an xgrammar-rs `GrammarCompiler` from our vocab.
pub(crate) fn make_xgrammar_compiler(
    vocab: &VocabularyIndex,
    stop_token_ids: &[u32],
) -> anyhow::Result<Arc<xgrammar_rs::GrammarCompiler>> {
    let tok = tokenizer_info_from_vocab(vocab, stop_token_ids)?;
    let compiler = xgrammar_rs::GrammarCompiler::new(tok).context("xgrammar GrammarCompiler::new")?;
    Ok(Arc::new(compiler))
}

/// Per-request grammar wrapper that holds the stateful xgrammar
/// `GrammarMatcher` plus the shared compiled grammar / tokenizer that
/// own its backing tables.
///
/// `xgrammar_rs::GrammarMatcher` is `Send` but `!Sync`. The trait
/// `StructuredOutputGrammar` requires `Send + Sync`, so we wrap the
/// matcher in a `Mutex`. In the engine pipeline each per-sequence
/// constraint is accessed serially, so the mutex contention is
/// effectively zero — but the type-level `Sync` requirement is met
/// and the wrapper composes safely with any future parallelism.
pub struct XGrammarGrammar {
    matcher: Mutex<xgrammar_rs::GrammarMatcher>,
    vocab_size: usize,
    // Held to keep the compiled grammar / tokenizer alive for the
    // matcher's lifetime. The `Arc`s also cheap-clone into new
    // matchers when the compiler factory re-instantiates.
    _grammar: Arc<xgrammar_rs::CompiledGrammar>,
}

impl XGrammarGrammar {
    pub(crate) fn from_compiled(
        grammar: Arc<xgrammar_rs::CompiledGrammar>,
        vocab_size: usize,
        max_rollback_tokens: i32,
    ) -> anyhow::Result<Self> {
        let matcher = grammar
            .new_matcher(max_rollback_tokens)
            .context("xgrammar CompiledGrammar::new_matcher")?;
        Ok(Self {
            matcher: Mutex::new(matcher),
            vocab_size,
            _grammar: grammar,
        })
    }
}

impl std::fmt::Debug for XGrammarGrammar {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("XGrammarGrammar")
            .field("vocab_size", &self.vocab_size)
            .finish_non_exhaustive()
    }
}

impl StructuredOutputGrammar for XGrammarGrammar {
    fn accept_tokens(&mut self, tokens: &[u32]) -> bool {
        let mut m = self.matcher.lock().expect("xgrammar matcher poisoned");
        for &t in tokens {
            match m.accept_token(t) {
                Ok(true) => {}
                Ok(false) | Err(_) => return false,
            }
        }
        true
    }

    fn fill_bitmask(&self, bitmask: &mut PackedBitmask, batch_index: usize) {
        // The `&self` signature means we cannot read-from-self and
        // write-to-bitmask simultaneously without splitting the
        // borrows — `row_mut` does that for us. Lock the matcher,
        // then write into the row.
        let m = self.matcher.lock().expect("xgrammar matcher poisoned");
        let row = bitmask.row_mut(batch_index);
        // If xgrammar reports "all allowed" (need_mask=false), we
        // explicitly fill the row with !0 to maintain the
        // adapter's invariant that a cleared row means "no token
        // allowed". The native ports follow the same convention.
        match m.fill_next_token_bitmask(row) {
            Ok(true) => {
                // Mask is already in `row`; nothing further to do.
            }
            Ok(false) => {
                // "Every token allowed" — set every bit.
                for w in row.iter_mut() {
                    *w = !0i32;
                }
            }
            Err(_) => {
                // Defensive: on a matcher error, mask everything
                // (caller falls through to error handling via the
                // adapter's terminated path on the next step).
                for w in row.iter_mut() {
                    *w = 0;
                }
            }
        }
    }

    fn rollback(&mut self, num_tokens: usize) {
        // `Rollback` errors only when num_tokens exceeds the matcher
        // budget — silently bound in that case, matching native
        // backend behaviour.
        let _ = self
            .matcher
            .lock()
            .expect("xgrammar matcher poisoned")
            .rollback(num_tokens);
    }

    fn is_terminated(&self) -> bool {
        self.matcher
            .lock()
            .expect("xgrammar matcher poisoned")
            .is_terminated()
    }

    fn reset(&mut self) {
        self.matcher
            .lock()
            .expect("xgrammar matcher poisoned")
            .reset();
    }
}

// Note: spec-string-to-`Arc<xgrammar_rs::CompiledGrammar>` is folded
// into the caller (`super::compiler::xgrammar_compile_to_arc`) so the
// async fast path can share the compiled grammar across requests.
// `XGrammarGrammar::from_compiled` above is what callers reach for.

#[cfg(test)]
mod tests {
    use super::*;

    /// Save the current env var (if any) and restore on drop, so
    /// `VLLM_XGRAMMAR_VOCAB_TYPE`-touching tests don't leak state to
    /// each other.
    ///
    /// Process-wide env mutation is intrinsically global state, so
    /// the multi-threaded test harness can race two tests' set/clear
    /// pairs unless we serialise them. The guard holds a static
    /// `Mutex` for its lifetime, ensuring only one env-touching test
    /// runs at a time regardless of `--test-threads`.
    struct EnvGuard {
        prev: Option<String>,
        _lock: std::sync::MutexGuard<'static, ()>,
    }
    static ENV_LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());
    impl EnvGuard {
        fn set(value: &str) -> Self {
            let lock = ENV_LOCK.lock().unwrap_or_else(|e| e.into_inner());
            let prev = std::env::var("VLLM_XGRAMMAR_VOCAB_TYPE").ok();
            std::env::set_var("VLLM_XGRAMMAR_VOCAB_TYPE", value);
            Self { prev, _lock: lock }
        }
        fn clear() -> Self {
            let lock = ENV_LOCK.lock().unwrap_or_else(|e| e.into_inner());
            let prev = std::env::var("VLLM_XGRAMMAR_VOCAB_TYPE").ok();
            std::env::remove_var("VLLM_XGRAMMAR_VOCAB_TYPE");
            Self { prev, _lock: lock }
        }
    }
    impl Drop for EnvGuard {
        fn drop(&mut self) {
            match self.prev.take() {
                Some(v) => std::env::set_var("VLLM_XGRAMMAR_VOCAB_TYPE", v),
                None => std::env::remove_var("VLLM_XGRAMMAR_VOCAB_TYPE"),
            }
            // _lock drops here, releasing the mutex.
        }
    }

    fn vocab_from(strings: &[&str]) -> VocabularyIndex {
        let bytes: Vec<Vec<u8>> = strings.iter().map(|s| s.as_bytes().to_vec()).collect();
        VocabularyIndex::from_token_bytes(bytes)
    }

    #[test]
    fn detect_raw_for_qwen_like_vocab() {
        let _g = EnvGuard::clear();
        // Plain UTF-8 fragments with no SP/BPE markers — Qwen3-style.
        let v = vocab_from(&["hello", " world", "привет", "你好", "!", "?", "{", "}"]);
        assert_eq!(detect_vocab_type(&v), xgrammar_rs::VocabType::Raw);
    }

    #[test]
    fn detect_byte_fallback_for_sentencepiece_markers() {
        let _g = EnvGuard::clear();
        // Any token of the exact form `<0xNN>` flips to ByteFallback.
        let v = vocab_from(&["hello", "<0x0A>", "world", "<0xFF>"]);
        assert_eq!(detect_vocab_type(&v), xgrammar_rs::VocabType::ByteFallback);
    }

    #[test]
    fn detect_byte_level_for_bpe_glyphs() {
        let _g = EnvGuard::clear();
        // U+0120 (Ġ) UTF-8 = 0xC4 0xA0 — HF BPE byte alphabet marker.
        let v = vocab_from(&["hello", "\u{0120}world"]);
        assert_eq!(detect_vocab_type(&v), xgrammar_rs::VocabType::ByteLevel);
    }

    #[test]
    fn env_override_wins_over_heuristic() {
        // Heuristic would say ByteFallback (sees <0x0A>), env says Raw.
        let _g = EnvGuard::set("raw");
        let v = vocab_from(&["<0x0A>", "x"]);
        assert_eq!(detect_vocab_type(&v), xgrammar_rs::VocabType::Raw);
    }

    #[test]
    fn env_override_accepts_case_variations() {
        let _g = EnvGuard::set("Byte_Fallback");
        // Pure-ASCII vocab — heuristic would land on Raw.
        let v = vocab_from(&["abc", "def"]);
        assert_eq!(detect_vocab_type(&v), xgrammar_rs::VocabType::ByteFallback);
    }
}

//! Grammar-based structured output with DFA-compiled bitmask constraints.
//!
//! This module provides high-performance constrained generation using
//! pre-compiled automaton states and packed bitmasks. Supported backends:
//! - Regex patterns compiled to DFA with per-state token bitmasks
//! - JSON Schema converted to regex then compiled to DFA
//! - EBNF/GBNF grammars (regular → DFA, recursive → pushdown automaton)

pub mod bitmask;
pub mod compiler;
pub mod vocabulary;

// Structured-output compilation. Removed the partial native Rust
// port (ebnf_backend / ebnf_parser / json_schema / regex_backend)
// in v1.8 — it never enforced JSON-Schema's `pattern + length` or
// strict-object key boundaries correctly (Bug 10 root cause).
// Production now goes through the xgrammar FFI bridge; the
// `xgrammar` feature gate stays so CPU dev / CI builds without
// CUDA can opt out of the C++ compile (at the cost of no
// structured output support in that configuration).
#[cfg(feature = "xgrammar")]
pub mod xgrammar_backend;
#[cfg(feature = "xgrammar")]
pub mod schema_to_ebnf;

pub use bitmask::PackedBitmask;
pub use compiler::GrammarCompiler;
pub use vocabulary::VocabularyIndex;

use crate::sampling::SamplingConstraint;

/// Core trait for grammar-based structured output constraints.
///
/// Unlike `SamplingConstraint` which works with decoded text,
/// `StructuredOutputGrammar` operates on token IDs and produces
/// packed bitmasks for O(vocab_size/32) logit masking.
pub trait StructuredOutputGrammar: Send + Sync {
    /// Feed accepted tokens into the grammar state machine.
    ///
    /// Returns `true` if all tokens were accepted (valid transitions),
    /// `false` if any token caused an invalid transition.
    fn accept_tokens(&mut self, tokens: &[u32]) -> bool;

    /// Fill the bitmask row for `batch_index` with allowed tokens
    /// given the current grammar state.
    fn fill_bitmask(&self, bitmask: &mut PackedBitmask, batch_index: usize);

    /// Roll back `num_tokens` from the state history.
    ///
    /// Used by speculative decoding to undo rejected draft tokens.
    fn rollback(&mut self, num_tokens: usize);

    /// Whether the grammar has reached a terminal/accepting state.
    fn is_terminated(&self) -> bool;

    /// Reset the grammar to its initial state.
    fn reset(&mut self);
}

/// Adapter that wraps a `StructuredOutputGrammar` as a `SamplingConstraint`.
///
/// Bridges the new grammar system into the existing sampling pipeline,
/// requiring zero changes to the 4 engine call sites.
pub struct GrammarConstraintAdapter {
    grammar: Box<dyn StructuredOutputGrammar>,
    vocab_size: usize,
    /// Reusable bitmask buffer (single-row, allocated once).
    bitmask_buf: PackedBitmask,
}

impl std::fmt::Debug for GrammarConstraintAdapter {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("GrammarConstraintAdapter")
            .field("vocab_size", &self.vocab_size)
            .field("is_terminated", &self.grammar.is_terminated())
            .finish()
    }
}

impl GrammarConstraintAdapter {
    pub fn new(grammar: Box<dyn StructuredOutputGrammar>, vocab_size: usize) -> Self {
        let bitmask_buf = PackedBitmask::new(1, vocab_size);
        Self {
            grammar,
            vocab_size,
            bitmask_buf,
        }
    }
}

impl SamplingConstraint for GrammarConstraintAdapter {
    fn mask_logits(&mut self, logits: &mut [f32], _generated_text: &str) -> anyhow::Result<()> {
        if self.grammar.is_terminated() {
            for logit in logits.iter_mut() {
                *logit = f32::NEG_INFINITY;
            }
            return Ok(());
        }

        self.bitmask_buf.set_all_zeros();
        self.grammar.fill_bitmask(&mut self.bitmask_buf, 0);
        self.bitmask_buf.apply_to_logits(logits, 0);
        // Padded-vocab tail mask. The grammar bitmask is sized to
        // the tokenizer's `vocab_size` (e.g. Qwen3 = 151669), but
        // the actual logits tensor often pads up to the next
        // multiple supported by the matmul (Qwen3 lm_head emits
        // 151936). Tokens in `[vocab_size, logits.len())` are
        // typically reserved/unused padding slots — the bitmask
        // doesn't touch them, so without an explicit -inf the
        // sampler can still draw one and produce undefined bytes.
        if logits.len() > self.vocab_size {
            for logit in &mut logits[self.vocab_size..] {
                *logit = f32::NEG_INFINITY;
            }
        }
        Ok(())
    }

    fn is_complete(&self, _generated: &[u32], _text: &str) -> bool {
        self.grammar.is_terminated()
    }

    fn reset(&mut self) {
        self.grammar.reset();
    }

    fn accept_token(&mut self, token_id: u32) -> bool {
        // Advance the underlying xgrammar matcher so the next
        // `fill_bitmask` reflects the post-`token_id` grammar state.
        // Without this hook the matcher stays at position 0 for the
        // entire stream and only the first token gets enforced.
        self.grammar.accept_tokens(&[token_id])
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::atomic::{AtomicBool, Ordering};
    use std::sync::Arc;

    /// Minimal mock grammar for testing the adapter.
    struct MockGrammar {
        terminated: Arc<AtomicBool>,
        allowed_tokens: Vec<u32>,
        accepted_count: usize,
    }

    impl MockGrammar {
        fn new(allowed_tokens: Vec<u32>) -> Self {
            Self {
                terminated: Arc::new(AtomicBool::new(false)),
                allowed_tokens,
                accepted_count: 0,
            }
        }
    }

    impl StructuredOutputGrammar for MockGrammar {
        fn accept_tokens(&mut self, tokens: &[u32]) -> bool {
            self.accepted_count += tokens.len();
            true
        }

        fn fill_bitmask(&self, bitmask: &mut PackedBitmask, batch_index: usize) {
            for &token_id in &self.allowed_tokens {
                bitmask.set_bit(batch_index, token_id as usize);
            }
        }

        fn rollback(&mut self, num_tokens: usize) {
            self.accepted_count = self.accepted_count.saturating_sub(num_tokens);
        }

        fn is_terminated(&self) -> bool {
            self.terminated.load(Ordering::Relaxed)
        }

        fn reset(&mut self) {
            self.accepted_count = 0;
            self.terminated.store(false, Ordering::Relaxed);
        }
    }

    #[test]
    fn adapter_masks_disallowed_tokens() {
        let grammar = MockGrammar::new(vec![2, 5, 7]);
        let mut adapter = GrammarConstraintAdapter::new(Box::new(grammar), 10);

        let mut logits = vec![1.0f32; 10];
        adapter.mask_logits(&mut logits, "").unwrap();

        // Only tokens 2, 5, 7 should remain finite
        for (i, &l) in logits.iter().enumerate() {
            if i == 2 || i == 5 || i == 7 {
                assert!(l.is_finite(), "token {i} should be allowed");
            } else {
                assert!(
                    l == f32::NEG_INFINITY,
                    "token {i} should be masked, got {l}"
                );
            }
        }
    }

    #[test]
    fn adapter_masks_all_when_terminated() {
        let grammar = MockGrammar::new(vec![1, 2, 3]);
        let terminated = grammar.terminated.clone();
        let mut adapter = GrammarConstraintAdapter::new(Box::new(grammar), 10);

        terminated.store(true, Ordering::Relaxed);

        let mut logits = vec![1.0f32; 10];
        adapter.mask_logits(&mut logits, "").unwrap();

        for &l in &logits {
            assert!(l == f32::NEG_INFINITY);
        }
    }

    #[test]
    fn adapter_is_complete_reflects_grammar() {
        let grammar = MockGrammar::new(vec![]);
        let terminated = grammar.terminated.clone();
        let adapter = GrammarConstraintAdapter::new(Box::new(grammar), 10);

        assert!(!adapter.is_complete(&[], ""));
        terminated.store(true, Ordering::Relaxed);
        assert!(adapter.is_complete(&[], ""));
    }

    #[test]
    fn adapter_reset_clears_grammar() {
        let grammar = MockGrammar::new(vec![1]);
        let terminated = grammar.terminated.clone();
        let mut adapter = GrammarConstraintAdapter::new(Box::new(grammar), 10);

        terminated.store(true, Ordering::Relaxed);
        assert!(adapter.is_complete(&[], ""));

        adapter.reset();
        assert!(!adapter.is_complete(&[], ""));
    }
}

